export default function UPMap({ onHover }) {
  const [scale, setScale] = useState(1);
  const [translate, setTranslate] = useState({ x: 0, y: 0 });
  const svgRef = useRef(null);
  const isPanning = useRef(false);
  const lastPoint = useRef({ x: 0, y: 0 });

  useEffect(() => {
    const svg = svgRef.current;
    if (!svg) return;

    const onWheel = (e) => {
      e.preventDefault();
      setScale((s) =>
        Math.min(Math.max(s + (e.deltaY > 0 ? -0.1 : 0.1), 0.8), 3),
      );
    };

    svg.addEventListener("wheel", onWheel, { passive: false });
    return () => svg.removeEventListener("wheel", onWheel);
  }, []);

  return (
    <svg
      ref={svgRef}
      viewBox="0 0 1024 1010"
      preserveAspectRatio="xMidYMid meet"
      className="up-map"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <g
        className="districts"
        transform={`translate(${translate.x} ${translate.y}) scale(${scale})`}
      >
        {districts.map((d, i) => (
          <a key={d.id} href={d.url}>
            <path
              d={districtPaths[d.id] || ""}
              data-id={d.id}
              data-name={d.name}
              className={`district-shape d${i + 1}`}
              onMouseEnter={(e) => onHover?.(e.target.dataset)}
              onMouseLeave={() => onHover?.(null)}
            />
          </a>
        ))}
      </g>
    </svg>
  );
}
